	/* @Test */
	public void testCaptureDebuggerMemoryBytesPlugin()
    {
		using (Transaction tx = tb.startTransaction())
{
			long snap = tb.trace.getTimeManager().createSnapshot("First").getKey();
			tb.trace.getMemoryManager()
					.addRegion(".text", Lifespan.nowOn(0), tb.range(0x00400000, 0x0040ffff),
						Set.of(TraceMemoryFlag.READ, TraceMemoryFlag.EXECUTE));

			TraceSymbolManager symbolManager = tb.trace.getSymbolManager();
			TraceNamespaceSymbol global = symbolManager.getGlobalNamespace();

			TraceSymbol mainLabel = symbolManager.labels()
					.create(snap, tb.addr(0x00400000), "main", global, SourceType.USER_DEFINED);
			/* @SuppressWarnings("unused") */
			TraceSymbol cloneLabel = symbolManager.labels()
					.create(snap, tb.addr(0x00400060), "clone", global, SourceType.USER_DEFINED);
			TraceSymbol childLabel = symbolManager.labels()
					.create(snap, tb.addr(0x00400034), "child", global, SourceType.USER_DEFINED);
			/* @SuppressWarnings("unused") */
			TraceSymbol exitLabel = symbolManager.labels()
					.create(snap, tb.addr(0x00400061), "exit", global, SourceType.USER_DEFINED);

			Assembler assembler = Assemblers.getAssembler(tb.trace.getProgramView());

			assembler.assemble(mainLabel.getAddress(),
				"PUSH RBP",
				"MOV RBP,RSP",
				"CALL clone",
				"TEST EAX,EAX",
				"JNZ child",
				"SUB RSP,0x10",
				"MOV dword ptr [RSP],0x6c6c6548",
				"MOV dword ptr [RSP+4],0x57202c6f",
				"MOV dword ptr [RSP+8],0x646c726f",
				"MOV word ptr [RSP+0xc],0x21",
				"CALL exit",
				"SUB RSP,0x10",
				"MOV dword ptr [RSP],0x2c657942",
				"MOV dword ptr [RSP+4],0x726f5720",
				"MOV dword ptr [RSP+8],0x21646c",
				"CALL exit");

			TraceThread thread = tb.getOrAddThread("[1]", snap);

			TraceMemorySpace regs =
				tb.trace.getMemoryManager().getMemoryRegisterSpace(thread, true);
			regs.setValue(snap, new RegisterValue(tb.language.getProgramCounter(),
				childLabel.getAddress().getOffsetAsBigInteger()));
		}

		traceManager.openTrace(tb.trace);
		traceManager.activateTrace(tb.trace);

		captureIsolatedProvider(typeof(DebuggerMemoryBytesProvider), 600, 600);
	}
